import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"21、【噬嗑】 震下离上","description":"子夏易传 - 21、【噬嗑】 震下离上","frontmatter":{"title":"21、【噬嗑】 震下离上","description":"子夏易传 - 21、【噬嗑】 震下离上"},"headers":[],"relativePath":"zh/classics/zixia/023.md","filePath":"zh/classics/zixia/023.md"}'),i={name:"zh/classics/zixia/023.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_21、【噬嗑】-震下离上" tabindex="-1">21、【噬嗑】 震下离上 <a class="header-anchor" href="#_21、【噬嗑】-震下离上" aria-label="Permalink to “21、【噬嗑】 震下离上”">​</a></h1><p>卦辞：噬嗑，亨，利用獄。</p><p>彖曰：頤中有物；曰噬嗑，噬嗑而亨。剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。</p><p>子夏：剛物在頤中，曰噬嗑。故噬而嗑之，其道乃通，刑以齊之者也。分剛於柔，分柔於剛，象交得其情也。動而明之義皆得於理也。雷震電照，威以明之，隱無不彰，果辨之也。柔上治之主也，雖不若剛徳，而運於無所用獄，而正之者也。</p><p>象曰：雷電噬嗑，先王以明罰敕法。</p><p>子夏：雷震電照，震而後明得於情實也，先王明其罪，告其法，然後誅之，而民莫怨其上也。</p><p>初九，屨校滅趾，无咎。</p><p>象曰：屨校滅趾，不行也。</p><p>子夏：屨校，以木禁足，如履屨也。罪其初過之小也，懲而戒之，校足没趾而已，其咎不行。小人福不至於大罪，戒為治者不可以不禁其微。</p><p>六二，噬膚滅鼻，无咎。</p><p>象曰：噬膚滅鼻，乘剛也。</p><p>子夏：噬而得位，物不敢抗，噬膚之易也。乘剛者恃其強也，不可以輕，輕則反為害矣。噬深而滅巳，然後免於咎，乃得於中也。</p><p>六三，噬腊肉遇毒，小吝无咎。</p><p>象曰：遇毒，位不當也。</p><p>子夏：柔僣剛位以之刑物，如噬腊之難也，則反謀為毒矣。慮毒而未傷，則懐懼而不果刑也，免之矣。噬之不盡，小吝者也。毒不終害，故無咎也。</p><p>九四，噬乾胏，得金矢，利艱貞吉。</p><p>象曰：利艱貞吉，未光也。</p><p>子夏：上近於尊，多懼之地，陰之位也。以斯用刑，未為得其道也，噬乾胏矣。果於剛直，無所回邪，曰金矢也。雖勇於敢位，未當也，豈足光哉，行法而已，艱以承之不失。其正得其吉也。</p><p>六五，噬乾肉，得黄金，貞厲，无咎。</p><p>象曰：貞厲，无咎，得當也。</p><p>子夏：柔以噬物亦為難也，噬乾肉矣。位尊民服，可以有制，因於剛之道也。治至於刑，正之危也。得中當理，故無咎也。</p><p>上九，何校滅耳，凶。</p><p>象曰：何校滅耳，聰不明也。</p><p>子夏：噬嗑之終，罪不可掩，至於極刑，故荷負其校以没於耳，凶滅身也。小人為過之初，皆知其然也。不虞咎，大而不可脱也，徒聞其言而不能辨其終也，故耳其没矣。聽之罪也。</p>',24)])])}const h=a(i,[["render",r]]);export{f as __pageData,h as default};
